// Fixtures for the sound pipeline. Nothing audible is committed: every WAV here is
// generated by ffmpeg `aevalsrc` on first use (atomic writes, safe under parallel test files) into
// fixtures/sound/out/ (git-ignored) and, for the committed kit-smoke-cues piece, its assets/.
//
//   click-120.wav    120 BPM, first click at 0.25 s, accented downbeat every fourth beat, soft pad; 8 s
//   music-120-kick.wav  the same grid under a dense pad with a kick on every beat (the piece's track); quiet-m30.wav is the click track at -30 LUFS
//   premix-m8.wav    a dense pre-mixed track at -8 LUFS (too loud to ship)
//
// Run `node fixtures/sound/setup.mjs` to (re)build them by hand.
import { spawnSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { detectBeats } from '../../scripts/beats.mjs';
import { measureLoudness } from '../../scripts/sound.mjs';

export const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const FIX = join(ROOT, 'fixtures', 'sound');
export const OUT = join(FIX, 'out');
export const PATTERNS = join(FIX, 'patterns');
export const PIECE = join(FIX, 'kit-smoke-cues');
export const CLICK_BPM = 120;
export const CLICK_OFFSET = 0.25;
export const CLICK_SECONDS = 8;

/** Ground truth of the click track: beat k sits at 0.25 + 0.5 k; the downbeats are every fourth. */
export const trueBeats = (n = Math.ceil((CLICK_SECONDS - CLICK_OFFSET) / 0.5)) => Array.from({ length: n }, (_, k) => CLICK_OFFSET + k * (60 / CLICK_BPM));

function ffmpegSync(args) {
  const r = spawnSync('ffmpeg', ['-hide_banner', '-nostdin', '-y', '-v', 'error', ...args], { encoding: 'utf8' });
  if (r.status !== 0) throw new Error(`ffmpeg ${args.join(' ')}: ${r.stderr}`);
}

// Written to a temp name then renamed, so a parallel test file never reads half a WAV.
function atomic(path, make) {
  if (existsSync(path)) return path;
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.${process.pid}.tmp.wav`;
  make(tmp);
  renameSync(tmp, path);
  return path;
}

// Parallel test files share these fixtures: write through a temp name, and not at all when unchanged.
function put(path, data) {
  if (existsSync(path) && readFileSync(path, 'utf8') === data) return;
  mkdirSync(dirname(path), { recursive: true });
  const tmp = `${path}.${process.pid}.tmp`;
  writeFileSync(tmp, data);
  renameSync(tmp, path);
}

const clickExpr = (offset, bpm, { accent = 0.9, plain = 0.5, pad = 'low', kick = false } = {}) => {
  const T = 60 / bpm;
  const k = `floor((t-${offset})/${T})`;
  const gain = `if(eq(mod(${k},4),0),${accent},${plain})`;
  const click = `if(gte(t,${offset}),exp(-mod(t-${offset},${T})*60)*sin(2*PI*1000*t)*${gain},0)`;
  const padExpr = pad === 'low' ? `0.06*(sin(2*PI*110*t)+0.7*sin(2*PI*165*t))` : `0.2*(sin(2*PI*440*t)+0.7*sin(2*PI*660*t))`;
  // a kick on every beat (a 60 Hz sine, 0.3 s), accented like the click: the grid of a track with kicks is usable (the kick check of `mm beats`)
  const kickExpr = kick ? `+if(gte(t,${offset}),exp(-mod(t-${offset},${T})*14)*sin(2*PI*60*t)*${gain}*0.8,0)` : '';
  return `${click}+${padExpr}${kickExpr}`;
};

export function ensureClick(path = join(OUT, 'click-120.wav')) {
  return atomic(path, (tmp) => ffmpegSync(['-f', 'lavfi', '-i', `aevalsrc='${clickExpr(CLICK_OFFSET, CLICK_BPM)}':s=48000:d=${CLICK_SECONDS}`, '-c:a', 'pcm_s16le', tmp]));
}

/** Rescales `src` to `lufs` integrated with a plain gain (float WAV, so a loud result is not clipped). */
async function scaleTo(src, dst, lufs) {
  const have = (await measureLoudness(src)).lufs;
  return atomic(dst, (tmp) => ffmpegSync(['-i', src, '-af', `volume=${(lufs - have).toFixed(3)}dB`, '-c:a', 'pcm_f32le', tmp]));
}

/** A music-like 120 BPM track: a dense pad with softer clicks, loud enough to reach -14 LUFS linearly. Used as the piece's track. */
export function ensureMusic() {
  return atomic(join(OUT, 'music-120-kick.wav'), (tmp) => ffmpegSync(['-f', 'lavfi', '-i', `aevalsrc='${clickExpr(CLICK_OFFSET, CLICK_BPM, { accent: 0.4, plain: 0.25, pad: 'high', kick: true })}':s=48000:d=${CLICK_SECONDS}`, '-c:a', 'pcm_s16le', tmp]));
}

/** A click track at another tempo (no accent pattern change), for the tempo estimator. */
export function ensureClickAt(bpm, offset = 0.4) {
  return atomic(join(OUT, `click-${bpm}.wav`), (tmp) => ffmpegSync(['-f', 'lavfi', '-i', `aevalsrc='${clickExpr(offset, bpm)}':s=48000:d=${CLICK_SECONDS}`, '-c:a', 'pcm_s16le', tmp]));
}

/** The click track cut to `seconds` (a track shorter than the picture). */
export function ensureShort(seconds = 3) {
  return atomic(join(OUT, `click-${seconds}s.wav`), (tmp) => ffmpegSync(['-i', ensureClick(), '-t', String(seconds), '-c:a', 'pcm_s16le', tmp]));
}

export async function ensureQuiet() { return scaleTo(ensureClick(), join(OUT, 'quiet-m30.wav'), -30); }

export async function ensurePremix() {
  const dense = atomic(join(OUT, 'dense.wav'), (tmp) => ffmpegSync(['-f', 'lavfi', '-i', `aevalsrc='0.3*sin(2*PI*220*t)+0.3*sin(2*PI*330*t)+0.2*sin(2*PI*440*t)*(0.6+0.4*sin(2*PI*2*t))':s=48000:d=${CLICK_SECONDS}`, '-c:a', 'pcm_f32le', tmp]));
  return scaleTo(dense, join(OUT, 'premix-m8.wav'), -8);
}

// --------------------------------------------------------------------------------------------
// pieces

const KIT = join(ROOT, 'fixtures', 'kit-smoke');
const rel = (from, to) => { const r = relative(from, to).split('\\').join('/'); return r.startsWith('.') ? r : `./${r}`; };

/** The kit-smoke film's style with its font paths re-pointed to fixtures/kit-smoke/assets from `dir`. */
export function styleFor(dir, patch = {}) {
  const style = JSON.parse(readFileSync(join(KIT, 'film', 'style.json'), 'utf8'));
  for (const face of Object.values(style.type)) for (const f of face.files) f.src = rel(dir, resolve(KIT, 'film', f.src)).replace(/^\.\//, '');
  return { ...style, ...patch, sound: { ...style.sound, ...(patch.sound ?? {}) } };
}

/** Cue plan for the kit-smoke-cues story: every cue lands on a 0.25 + 0.5 k beat. */
export function cueStory(dir, { track = 'assets/audio/track.wav', beats = 'assets/beats.json', bpm = 120, cues } = {}) {
  const base = JSON.parse(readFileSync(join(KIT, 'film', 'story.json'), 'utf8'));
  const [intro, outro] = base.scenes;
  const c = cues ?? ['tick', 'hit', 'tick', 'tick'];
  const beat = (b, at, cue) => { const o = { ...b, at }; delete o.cue; if (cue) o.cue = cue; return o; };
  intro.beats[0] = beat(intro.beats[0], 0.25, c[0]);
  intro.beats[1] = beat(intro.beats[1], 1.25, c[1]);
  outro.beats[0] = beat(outro.beats[0], 0.25, c[2]);
  outro.beats[1] = beat(outro.beats[1], 0.75, c[3]);
  return { ...base, id: 'kit-smoke-cues', title: 'kit-smoke film with cues on a 120 BPM grid', audio: { track, bpm, beats } };
}

/** Writes index.html, story.json, style.json into `dir` (anywhere under the repo). */
export function writePiece(dir, { story, style }) {
  mkdirSync(dir, { recursive: true });
  const html = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width">
  <title>${story.id}</title>
</head>
<body>
  <script type="module">
    import { mount } from '${rel(dir, join(ROOT, 'runtime/kit/kit.js'))}';
    const load = (f) => fetch(new URL(f, import.meta.url)).then((r) => r.json());
    const [story, style] = await Promise.all([load('story.json'), load('style.json')]);
    await mount({ story, style, patternsBase: new URL('${rel(dir, join(KIT, 'patterns')) }/', import.meta.url) });
  </script>
</body>
</html>
`;
  put(join(dir, 'index.html'), html);
  put(join(dir, 'story.json'), JSON.stringify(story, null, 2) + '\n');
  put(join(dir, 'style.json'), JSON.stringify(style, null, 2) + '\n');
  return dir;
}

/** The committed piece's generated assets: the track and its beat grid (from `beats --bpm 120`). */
export async function ensurePiece() {
  const track = join(PIECE, 'assets', 'audio', 'track.wav');
  const grid = join(PIECE, 'assets', 'beats.json');
  if (!existsSync(track)) { mkdirSync(dirname(track), { recursive: true }); const tmp = `${track}.${process.pid}.tmp`; copyFileSync(ensureMusic(), tmp); renameSync(tmp, track); }
  if (!existsSync(grid)) put(grid, JSON.stringify(await detectBeats(track, { bpm: CLICK_BPM }), null, 2) + '\n');
  return PIECE;
}

/** A throwaway copy of the cue piece under fixtures/sound/out/<name>/ with the story/style adjusted. */
export async function variant(name, { story = {}, style = {}, track, beats, cues, edit } = {}) {
  const dir = join(OUT, name);
  rmSync(join(dir, 'out'), { recursive: true, force: true });       // a variant starts with nothing built
  const toRel = (abs) => (abs == null ? null : rel(dir, abs).replace(/^\.\//, ''));
  const base = cueStory(dir, {
    cues,
    track: track === null ? null : toRel(track ?? join(PIECE, 'assets/audio/track.wav')),
    beats: beats === null ? null : toRel(beats ?? join(PIECE, 'assets/beats.json')),
  });
  const merged = { ...base, ...story, audio: { ...base.audio, ...(story.audio ?? {}) } };
  edit?.(merged);
  writePiece(dir, { story: merged, style: styleFor(dir, style) });
  return dir;
}

/**
 * A silent MP4 of the piece at `fps` (default 10, small, for the mux): three real frames from the
 * page via framePng, held to the film's length. Cached at OUT/<name>.mp4.
 */
export async function ensureSilentMp4(pieceDir = PIECE, name = 'picture', { fps = 10, seconds = 6 } = {}) {
  const dst = join(OUT, `${name}.mp4`);
  if (existsSync(dst)) return dst;
  const { openPiece, framePng } = await import('../../scripts/lib/browser.mjs');
  const piece = await openPiece(pieceDir);
  mkdirSync(OUT, { recursive: true });
  const tmp = join(OUT, `.${name}.${process.pid}`);
  mkdirSync(tmp, { recursive: true });
  try {
    const list = [];
    for (const [i, t] of [0.5, seconds / 2 + 0.5, seconds - 0.2].entries()) {
      const f = join(tmp, `f${i}.png`);
      writeFileSync(f, await framePng(piece.page, t));
      list.push(`file '${f}'`, `duration ${seconds / 3}`);
    }
    list.push(list[list.length - 2]);
    writeFileSync(join(tmp, 'list.txt'), list.join('\n') + '\n');
    ffmpegSync(['-f', 'concat', '-safe', '0', '-i', join(tmp, 'list.txt'), '-vf', `fps=${fps},scale=480:-2,format=yuv420p`, '-t', String(seconds), '-an',
      '-c:v', 'libx264', '-preset', 'ultrafast', '-movflags', '+faststart', `${dst}.${process.pid}.tmp.mp4`]);
    renameSync(`${dst}.${process.pid}.tmp.mp4`, dst);
  } finally { await piece.close(); }
  return dst;
}

/** Copies the silent picture into <dir>/out/ under a name the sound verb treats as a format render. */
export async function withPicture(dir, name = 'kit-smoke_16x9.mp4') {
  const src = await ensureSilentMp4();
  mkdirSync(join(dir, 'out'), { recursive: true });
  copyFileSync(src, join(dir, 'out', name));
  return join(dir, 'out', name);
}

// --------------------------------------------------------------------------------------------
// negatives (AXIOM 5): one fixture piece per rule, each of which its rule must refuse

export const NEG = join(ROOT, 'fixtures', 'negatives');
const gridBeats = Array.from({ length: 16 }, (_, k) => CLICK_OFFSET + k * 0.5);

/**
 * Writes fixtures/negatives/{G-PEAK,W-LOUDNESS,W-CUE,W-MIX}/ (committed: story, style, page; W-CUE's grid) and
 * ships a clipping mix at G-PEAK/out/mix.wav and a quiet one at W-LOUDNESS/out/mix.wav (tracked through .gitignore exceptions, unlike the rest of out/).
 */
export async function ensureNegatives() {
  // The three sound negatives are tracked fixtures built from fixtures/negatives/_base/film
  // by the gate lane (G-PEAK and W-LOUDNESS ship their out/mix.wav through .gitignore exceptions). Rewriting them
  // here would undo that, so this only returns their paths.
  return { peak: join(NEG, 'G-PEAK'), quiet: join(NEG, 'W-LOUDNESS'), cue: join(NEG, 'W-CUE'), mix: join(NEG, 'W-MIX') };
}

/** A gate context for a piece directory, built without a browser (schedule from the pure kit). */
export async function ctxFor(dir, { schedule: sched, patternsBase = PATTERNS } = {}) {
  const { schedule } = await import('../../runtime/kit/schedule.js');
  const story = JSON.parse(readFileSync(join(dir, 'story.json'), 'utf8'));
  const style = JSON.parse(readFileSync(join(dir, 'style.json'), 'utf8'));
  return { dir, story, style, format: story.formats[0], page: null, mm: null, schedule: sched ?? schedule(story, style), meta: {}, errors: [], patternsBase };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await ensurePiece(); await ensureQuiet(); await ensureNegatives();
  console.log(`sound fixtures ready in ${OUT} and ${PIECE}`);
}
